# 1. Register the cross-account principal as a data lake admin recipient for the share (run in Account A)
aws lakeformation grant-permissions \
  --principal DataLakePrincipalIdentifier=arn:aws:iam::222222222222:role/DataScienceAnalystRole \
  --resource '{
    "TableWithColumns": {
      "DatabaseName": "customer_db",
      "Name": "customers",
      "ColumnNames": ["customer_id", "signup_date", "region"]
    }
  }' \
  --permissions "SELECT" \
  --permissions-with-grant-option []

# 2. Confirm the grant landed correctly
aws lakeformation list-permissions \
  --resource '{
    "Table": {
      "DatabaseName": "customer_db",
      "Name": "customers",
      "CatalogId": "111111111111"
    }
  }'

# 3. In Account B: the analyst's role also needs an IAM policy allowing it to call
# glue:GetTable / athena:StartQueryExecution against the shared resource -- Lake Formation
# grants the DATA permission, IAM must separately allow the API call itself.

// --- Account A (111111111111): bucket policy on the curated-data bucket ---
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowAccountBGlueRoleRead",
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::222222222222:role/GlueCrossAccountReadRole"
      },
      "Action": ["s3:GetObject", "s3:ListBucket"],
      "Resource": [
        "arn:aws:s3:::curated-data-bucket",
        "arn:aws:s3:::curated-data-bucket/exports/*"
      ]
    }
  ]
}

// --- Account B (222222222222): identity policy attached to the Glue job role,
// granting it permission to use these S3 actions against Account A's bucket ---
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": ["s3:GetObject", "s3:ListBucket"],
      "Resource": [
        "arn:aws:s3:::curated-data-bucket",
        "arn:aws:s3:::curated-data-bucket/exports/*"
      ]
    }
  ]
}

// --- Account B: trust policy on GlueCrossAccountReadRole, allowing Glue's service ---
// --- principal to assume it (no cross-account assume-role is actually needed here ---
// --- since this is resource-based S3 access, not role-chaining) ---
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": { "Service": "glue.amazonaws.com" },
      "Action": "sts:AssumeRole"
    }
  ]
}

# Crawler configuration (AWS CLI) with an exclude pattern for temp/in-progress files
aws glue create-crawler \
  --name orders-landing-crawler \
  --role arn:aws:iam::111111111111:role/GlueCrawlerRole \
  --database-name landing_db \
  --targets '{
    "S3Targets": [
      {
        "Path": "s3://landing-bucket/orders/",
        "Exclusions": ["**.tmp", "**/_tmp*", "**/*.inprogress"]
      }
    ]
  }' \
  --schema-change-policy '{
    "UpdateBehavior": "UPDATE_IN_DATABASE",
    "DeleteBehavior": "LOG"
  }'

# Glue job: enable bookmarks so only new S3 objects are processed each run
aws glue create-job \
  --name orders-etl-job \
  --role arn:aws:iam::111111111111:role/GlueETLRole \
  --command '{"Name": "glueetl", "ScriptLocation": "s3://scripts-bucket/orders_etl.py"}' \
  --default-arguments '{
    "--job-bookmark-option": "job-bookmark-enable",
    "--TempDir": "s3://scripts-bucket/temp/"
  }'

{
  "Comment": "Glue then EMR with retry and catch",
  "StartAt": "RunGlueJob",
  "States": {
    "RunGlueJob": {
      "Type": "Task",
      "Resource": "arn:aws:states:::glue:startJobRun.sync",
      "Parameters": {
        "JobName": "orders-etl-job"
      },
      "Retry": [
        {
          "ErrorEquals": ["Glue.ConcurrentRunsExceededException", "States.Timeout"],
          "IntervalSeconds": 30,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.error",
          "Next": "NotifyFailure"
        }
      ],
      "Next": "RunEmrStep"
    },
    "RunEmrStep": {
      "Type": "Task",
      "Resource": "arn:aws:states:::elasticmapreduce:addStep.sync",
      "Parameters": {
        "ClusterId": "j-EXAMPLECLUSTERID",
        "Step": {
          "Name": "AggregateOrders",
          "ActionOnFailure": "CONTINUE",
          "HadoopJarStep": {
            "Jar": "command-runner.jar",
            "Args": ["spark-submit", "s3://scripts-bucket/aggregate_orders.py"]
          }
        }
      },
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.error",
          "Next": "NotifyFailure"
        }
      ],
      "End": true
    },
    "NotifyFailure": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sns:publish",
      "Parameters": {
        "TopicArn": "arn:aws:sns:us-east-1:111111111111:pipeline-failures",
        "Message.$": "$.error"
      },
      "End": true
    }
  }
}

